style.css:
@-moz-document domain("hexagon.pw") {
* {
        font-size: 12px;
        font-family: Verdana, Arial, Helvetica, sans-serif;
    }
    .Title {
        font-size: 18px;
    }
    a.Title:link, a.Title:visited, a.Title:active {
        text-decoration: none;
    }
    a.Title:hover {
        text-decoration: underline;
    }
    .Header {
        font-size: 14px;
        color: #004080; /* Changed to a bluer shade */
    }
    .Banner {
        padding: 8px;
    }
    .BannerText {
        font-weight: bold;
        color: white;
    }
    a.BannerText:link, a.BannerText:visited, a.BannerText:active {
        text-decoration: none;
        color: white;
    }
    a.BannerText:hover {
        text-decoration: underline;
        color: white;
    }
    .OKCancelButton {
        width: 80px;
    }
    .SmallerFont {
        font-size: 10px;
    }
    .RP {
        font-size: 10px;
        color: #cc3366;
    }
    .MenuItem {
        color: white;
        font-size: 18px;
        line-height: 2em;
    }
    a.MenuItem:link, a.MenuItem:visited, a.MenuItem:active {
        text-decoration: none;
    }
    a.MenuItem:hover {
        text-decoration: underline;
    }
    .Legal {
        font-size: 9px;
    }
    .Toolbox {
        background-color: buttonface;
        padding: 2px;
    }
    .ToolboxItem {
        border-color: window;
        border-style: solid;
        border-width: 2px;
        width: 54px;
        height: 54px;
    }
    .Grid {
        background-color: white;
        border-color: #cccccc;
        border-width: 1px;
        border-style: solid;
    }
    .GridHeader {
        color: white;
        background-color: lightsteelblue;
    }
    .GridItem {
        color: #000066;
    }
    .GridFooter {
        color: #000066;
        background-color: white;
    }
    .GridPager {
        color: #000066;
        background-color: white;
        text-align: center;
    }
    a.GridLink:link, a.GridLink:visited, a.GridLink:active {
        text-decoration: none;
    }
    a.GridLink:hover {
        text-decoration: underline;
    }
    .GridSelectedItem {
        color: white;
        background-color: #669999;
    }
    H1 {
        font-weight: bold;
        font-size: larger;
    }
    .LogInButton {
        background-color: white;
        color: #0000c0;
    }
    .SignUpButton {
        background-color: #ff8000;
        color: #0000c0;
    }
    Help.TABLE {
        border-right: black thin solid;
        border-top: black thin solid;
        border-left: black thin solid;
        border-bottom: black thin solid;
    }
    HELP.TR {
        border-top: gray thin solid;
        border-bottom: gray thin solid;
    }
    HELP.TD {}
}
